FILES={'cache_policy.py': '"""Reuse accepted S\'s single-frame encoding + 8-frame latent history.\nKeep this run\'s original Normal sampling, global RNG and done handling.\nNumerical admission uses the accepted S tolerance, not bitwise equality.\n"""\nimport torch,collections,copy\n\ndef encode(front,d):\n    x={\'obs\':{k:v.clone() for k,v in d[\'obs\'].items()},\'task_emb\':d[\'task_emb\'].clone(),\'masks\':d[\'masks\'].clone()}\n    return front.spatial_encode(front.preprocess_input(x,train_mode=False))\n\ndef cached_get_action(self,data):\n    self.eval()\n    with torch.no_grad():\n        n=next(iter(data[\'obs\'].values())).shape[1]\n        assert 1<=n<=8\n        # Original evaluator supplies the complete raw history. Encode only its\n        # newest frame; preserve original temporal/head/sample operation order.\n        newest=dict(obs={k:v[:,-1:].contiguous() for k,v in data[\'obs\'].items()},task_emb=data[\'task_emb\'],masks=data[\'masks\'])\n        self.latent_queue.append(encode(self,newest))\n        self.latent_queue=self.latent_queue[-8:]\n        assert len(self.latent_queue)==n,\'History/reset mismatch\'\n        x=torch.cat(self.latent_queue,dim=1)\n        x_temp=self.temporal_encode(x)\n        dist=self.policy_head(x_temp[:,-1,:],train=False)\n        action=dist.sample().detach().cpu()\n        return action.view(action.shape[0],-1).numpy()\n\ndef admission(p,shape,instr,mask,rng,restore_rng):\n    """Same 1..8 history, feature/GMM-parameter 1e-4 tests as accepted S."""\n    saved=rng();was_training=p.training;p.eval();before={k:v.detach().clone() for k,v in p.state_dict().items()}\n    try:\n        gen=torch.Generator().manual_seed(20261024)\n        obs={k:torch.rand((2,8,*v),generator=gen).cuda() for k,v in shape[\'all_shapes\'].items()}\n        base=dict(task_emb=instr.repeat(2,1).cuda(),masks=mask.repeat(2,1).cuda())\n        with torch.no_grad():\n            frames=[encode(p,dict(obs={k:v[:,i:i+1] for k,v in obs.items()},**base)) for i in range(8)]\n            rows=[]\n            for n in range(1,9):\n                whole=encode(p,dict(obs={k:v[:,:n] for k,v in obs.items()},**base));cached=torch.cat(frames[:n],1)\n                assert torch.allclose(whole,cached,atol=1e-4,rtol=1e-4)\n                q0=p.policy_head.forward_fn(p.temporal_encode(whole)[:,-1]);q1=p.policy_head.forward_fn(p.temporal_encode(cached)[:,-1])\n                assert all(torch.allclose(x,y,atol=1e-4,rtol=1e-4) for x,y in zip(q0,q1))\n                rows.append(dict(length=n,max_feature_abs=float((whole-cached).abs().max()),max_param_abs=max(float((x-y).abs().max()) for x,y in zip(q0,q1))))\n        assert all(torch.equal(before[k],v) for k,v in p.state_dict().items())\n        return dict(status=\'PASS_ACCEPTED_S_CACHE_TOLERANCE\',atol=1e-4,rtol=1e-4,cache_parity=rows,frontend_calls=16,policy_parameter_calls=16,optimizer_calls=0,environments=0,model_unchanged=True,bitwise_equivalence_claim=False)\n    finally:\n        p.latent_queue=[];p.train(was_training);restore_rng(saved)\n', 'validate_cache.py': '"""Offline admission and reference S-cache action parity; never creates envs."""\nimport sys,json,time,types,hashlib,copy\nfrom pathlib import Path\nimport torch,numpy as np\nfrom coreset_exp.model import cfg,data_setup,complete,strict_downstream\nfrom coreset_exp.common import O,rng,restore_rng,sha\nfrom libero.lifelong.utils import control_seed\nfrom cache_policy import encode,cached_get_action,admission\ndef equal(a,b):\n    if torch.is_tensor(a):return torch.equal(a,b)\n    if isinstance(a,np.ndarray):return np.array_equal(a,b)\n    if isinstance(a,dict):return a.keys()==b.keys() and all(equal(a[k],b[k]) for k in a)\n    if isinstance(a,(list,tuple)):return len(a)==len(b) and all(equal(x,y) for x,y in zip(a,b))\n    return a==b\ndef main():\n    torch.cuda.set_per_process_memory_fraction(.23);torch.backends.cudnn.benchmark=True;control_seed(809110)\n    c=cfg(\'eval\');b,_,shape=data_setup(c,False);c.shape_meta=shape;p=complete(c,shape).eval().requires_grad_(False)\n    instr,mask=b.get_task_emb(8);results=[];case=O.name\n    stages=range(6,10) if case.startswith(\'OBJECT\') else [None]\n    for stage in stages:\n        if stage is not None:\n            cp=O/\'random/models\'/f\'mlrifa_{stage}_model_ep99.pth\';strict_downstream(p,cp)\n        before=rng();proof=admission(p,shape,instr,mask,rng,restore_rng);assert equal(before,rng())\n        gen=torch.Generator().manual_seed(20261024)\n        obs={k:torch.rand((2,10,*v),generator=gen).cuda() for k,v in shape[\'all_shapes\'].items()}\n        base=dict(task_emb=instr.repeat(2,1).cuda(),masks=mask.repeat(2,1).cuda());p.reset();history=[];rows=[]\n        with torch.no_grad():\n            for i in range(10):\n                d=dict(obs={k:v[:,max(0,i-7):i+1].contiguous() for k,v in obs.items()},**base)\n                saved=rng();a=cached_get_action(p,d);after=rng();restore_rng(saved)\n                new=dict(obs={k:v[:,i:i+1] for k,v in obs.items()},**base)\n                history.append(encode(p,new));history=history[-8:]\n                dist=p.policy_head(p.temporal_encode(torch.cat(history,1))[:,-1],train=False)\n                ref=dist.sample().detach().cpu().numpy()\n                assert np.array_equal(a,ref) and equal(after,rng())\n                rows.append(dict(step=i+1,history=min(i+1,8),same_as_reference_cached_action=True,same_rng=True))\n        results.append(dict(stage=stage,proof=proof,wrapper_parity=rows,checkpoint_sha256=sha(cp) if stage is not None else sha(c.pretrain)))\n    print(\'RESULT_JSON=\'+json.dumps(dict(status=\'PASS_CACHE_TOLERANCE_AND_REFERENCE_WRAPPER\',case=case,stages=results,new_optimizer=0,new_environment=0,production_writes=0)))\nif __name__==\'__main__\':main()\n'}
from pathlib import Path
import sys,json,subprocess,hashlib,time
Q=Path('/data/mlr_ifa/experiment_workspaces/MLR_IFA_ALIGN_RANDOM_OBJECT_GOAL41_42_43_20261110_v2')
